window.VOCAB_LWS_META = [{"batch":2,"added":"2026-11-07","lesson":1,"lesson_title":"Glück im Alltag","book":"Schritte plus Neu 5 · Lernwortschatz","pages":"LWS 171–175","tips":[{"text":"Das Wort *als* hat mehrere Bedeutungen. Schreiben Sie zu jeder Bedeutung einen Satz.","text_en":"The word *als* has several meanings. Write a sentence for each meaning.","example":"Wann? Als ich drei Jahre alt war, bekam ich mein erstes Haustier.","answer":["Vergleich: Jan ist älter als Julian","Berufsbezeichnung: Er arbeitet als Arzt"],"note":"Three meanings: *als* = when (one event in the past, verb at the end), *als* after a comparative = than, *als* + job or role = as. For something that happened again and again in the past, use *wenn*, not *als*."}],"count":78},{"batch":3,"added":"2026-11-07","lesson":2,"lesson_title":"Unterhaltung","book":"Schritte plus Neu 5 · Lernwortschatz","pages":"LWS 175–179","tips":[{"text":"Schreiben Sie eine kleine Geschichte mit den Wörtern aus der Lektion.","text_en":"Write a short story with the words from the lesson.","example":"Meine Geschichte handelt von einem unglaublichen Abenteuer: Ich begegnete in einer grossen Stadt dem Star aus meiner Lieblingsserie. Unglaublich! Ich war optimistisch, dass …","answer":["… ich ein Foto mit ihm machen kann. Ich hatte zwar nicht den Mut, ihn anzusprechen, aber dann kam die grosse Überraschung: Er fragte mich, wo der Bahnhof ist!"],"note":"A model answer; yours can be quite different. In English: '… that I could take a photo with him. I didn't have the courage to talk to him, it's true, but then came the big surprise: he asked me where the station was!' It reuses *zwar … aber*, *der Mut* and *die Überraschung* from Lektion 1."}],"count":66},{"batch":4,"added":"2026-11-07","lesson":3,"lesson_title":"Gesund bleiben","book":"Schritte plus Neu 5 · Lernwortschatz","pages":"LWS 179–183","tips":[{"text":"Lernen Sie typische Wendungen zusammen.","text_en":"Learn typical phrases together.","example":"den Blutdruck messen, Blut abnehmen, das Gewicht prüfen, den Bauch …","answer":["den Bauch untersuchen","jemanden impfen","Medikamente verschreiben","jemanden krankschreiben","ein Gespräch führen","einen Termin vereinbaren","Sport treiben","auf Schokolade verzichten"],"note":"*den Bauch untersuchen* completes the book's list (examine the abdomen). The others are word pairs from this lesson worth learning as one unit: get vaccinated, prescribe medicine, sign someone off sick, hold a conversation, make an appointment, do sport, give up chocolate."}],"count":68},{"batch":1,"added":"2026-11-06","lesson":4,"lesson_title":"Sprachen","book":"Schritte plus Neu 5 · Lernwortschatz","pages":"LWS 184–187","tips":[{"text":"Im Deutschen enden viele Sprachen auf «-isch». Schreiben Sie.","text_en":"In German, many languages end in -isch. Write some.","example":"Griechisch, Französisch, …","answer":["Englisch","Spanisch","Italienisch","Portugiesisch","Russisch","Polnisch","Türkisch","Arabisch","Chinesisch","Japanisch","Ungarisch","Albanisch"],"note":"Language names are neuter and usually have no article: *Ich lerne Spanisch.* Not every language ends in *-isch*: *Deutsch*, *Hindi* and *Swahili* don't."}],"count":60}];
